import type { Card } from '@wp/cards';
import { createRng, type Rng } from '@wp/game-core';
import { cardId, scoreIds } from './eval';
import { PREFLOP_EQUITY } from './preflop-table';

/**
 * Seeded Monte Carlo equity and the preflop hand table.
 *
 * Starting hands come in 169 classes: 13 pairs, 78 suited and 78 offsuit combinations. A class is stored in a
 * 13 × 13 matrix: pairs on the diagonal, suited hands at [high][low], offsuit hands at [low][high]
 * (`classIndex = row * 13 + column`). `PREFLOP_EQUITY` (generated by `computePreflopEquity`, see
 * `preflop-table.ts`) is each class's chance to win against one random hand when all five board cards are dealt.
 */

/** Class index (0–168) of two hole card ids. */
export function classOfIds(a: number, b: number): number {
  const ra = a % 13;
  const rb = b % 13;
  const high = Math.max(ra, rb);
  const low = Math.min(ra, rb);
  if (high === low) return high * 13 + high;
  const suited = Math.floor(a / 13) === Math.floor(b / 13);
  return suited ? high * 13 + low : low * 13 + high;
}

export const classOf = (hole: readonly Card[]): number => classOfIds(cardId(hole[0] as Card), cardId(hole[1] as Card));

/** Number of concrete two-card combinations in a class (pairs 6, suited 4, offsuit 12). */
export function combosOf(classIndex: number): number {
  const row = Math.floor(classIndex / 13);
  const col = classIndex % 13;
  if (row === col) return 6;
  return row > col ? 4 : 12;
}

/** Name like "AKs", "TT", "72o". */
export function className(classIndex: number): string {
  const row = Math.floor(classIndex / 13);
  const col = classIndex % 13;
  const letters = '23456789TJQKA';
  const high = letters[Math.max(row, col)] as string;
  const low = letters[Math.min(row, col)] as string;
  if (row === col) return high + low;
  return high + low + (row > col ? 's' : 'o');
}

/** A representative pair of card ids for a class (equity does not depend on the concrete suits). */
function representative(classIndex: number): [number, number] {
  const row = Math.floor(classIndex / 13);
  const col = classIndex % 13;
  const high = Math.max(row, col);
  const low = Math.min(row, col);
  if (row === col) return [high, 13 + high];
  return row > col ? [high, low] : [high, 13 + low];
}

/** Equity of a class against one random hand, by `iterations` seeded random deals. */
export function computePreflopEquity(classIndex: number, iterations: number, seed: number): number {
  const rng = createRng((seed ^ Math.imul(classIndex + 1, 0x9e3779b1)) >>> 0);
  const [a, b] = representative(classIndex);
  return equityVsRandom([a, b], [], 1, iterations, rng, () => true);
}

/**
 * Percentile of every class: the share of all 1,326 starting hands that are at least as strong (by
 * PREFLOP_EQUITY). Aces have about 0.005, the weakest hands 1.
 */
export const PREFLOP_PERCENTILE: readonly number[] = (() => {
  const order = Array.from({ length: 169 }, (_, i) => i).sort((x, y) => (PREFLOP_EQUITY[y] as number) - (PREFLOP_EQUITY[x] as number) || x - y);
  const result = new Array<number>(169).fill(1);
  let cumulative = 0;
  for (const index of order) {
    cumulative += combosOf(index);
    result[index] = cumulative / 1326;
  }
  return result;
})();

const pool = new Int32Array(52);
const mine = new Int32Array(7);
const theirs = new Int32Array(7);
const oppCards = new Int32Array(10);
const boardIds = new Int32Array(5);

/**
 * Monte Carlo equity of `holeIds` (with known `boardIdsIn`) against `opponents` unknown hands. `accept(i, a, b)`
 * may reject a sampled hand for opponent i (range modelling); after a few rejections the sample is kept anyway.
 * A won pot counts 1, a split among k winners 1/k.
 */
function equityVsRandom(
  holeIds: readonly number[],
  boardIdsIn: readonly number[],
  opponents: number,
  iterations: number,
  rng: Rng,
  accept: (opponent: number, a: number, b: number) => boolean
): number {
  const known = new Set<number>([...holeIds, ...boardIdsIn]);
  let size = 0;
  for (let id = 0; id < 52; id++) if (!known.has(id)) pool[size++] = id;
  let total = 0;
  for (let it = 0; it < iterations; it++) {
    let end = size;
    const draw = (): number => {
      const j = Math.floor(rng.next() * end);
      const card = pool[j] as number;
      pool[j] = pool[end - 1] as number;
      pool[end - 1] = card;
      end--;
      return card;
    };
    for (let o = 0; o < opponents; o++) {
      let a = draw();
      let b = draw();
      for (let tries = 0; tries < 12 && !accept(o, a, b); tries++) {
        end += 2;
        a = draw();
        b = draw();
      }
      oppCards[o * 2] = a;
      oppCards[o * 2 + 1] = b;
    }
    for (let k = 0; k < boardIdsIn.length; k++) boardIds[k] = boardIdsIn[k] as number;
    for (let k = boardIdsIn.length; k < 5; k++) boardIds[k] = draw();
    mine[0] = holeIds[0] as number;
    mine[1] = holeIds[1] as number;
    for (let k = 0; k < 5; k++) {
      mine[k + 2] = boardIds[k] as number;
      theirs[k + 2] = boardIds[k] as number;
    }
    const my = scoreIds(mine, 7);
    let best = true;
    let ties = 0;
    for (let o = 0; o < opponents && best; o++) {
      theirs[0] = oppCards[o * 2] as number;
      theirs[1] = oppCards[o * 2 + 1] as number;
      const score = scoreIds(theirs, 7);
      if (score > my) best = false;
      else if (score === my) ties++;
    }
    if (best) total += 1 / (ties + 1);
  }
  return iterations > 0 ? total / iterations : 0;
}

/**
 * Equity of `hole` with the known `board` against opponents whose hands lie in the top `ranges[i]` share of
 * starting hands (1 = any two cards).
 */
export function estimateEquity(hole: readonly Card[], board: readonly Card[], ranges: readonly number[], iterations: number, rng: Rng): number {
  if (ranges.length === 0) return 1;
  const accept = (o: number, a: number, b: number) => {
    const range = ranges[o] as number;
    return range >= 1 || (PREFLOP_PERCENTILE[classOfIds(a, b)] as number) <= range;
  };
  return equityVsRandom(hole.map(cardId), board.map(cardId), ranges.length, iterations, rng, accept);
}
